<?php if ( ! defined('BASEPATH')) exit('No direct script access allowed');class mdyeintype extends CI_Controller {    private $limit = 5;    public function __construct() {        parent::__construct();        $this->load->model(CNFCOMPANY."/mdyeintypemodel");        $this->load->helper('cookie');        $this->load->helper('xssclean');        $this->load->library('email');        $this->load->helper('email');        $this->load->helper('common');        fnIfCheckUserLoggedIn();    }    public function addeditdyeintype() {        $ArrData												= array('ArrBasicInfo'=>array(),'VarId'=>'',            'VarNew'=>0);        $VarId		    									    = $this->uri->segment(4);        if($VarId<>'' && base64_decode(urldecode($VarId))) {            $VarUserId                                          = base64_decode(urldecode($VarId));            $ArrResults     									= $this->mdyeintypemodel->fnGetDyeingTypeInfo('','',                $VarUserId);            $ArrData['ArrBasicInfo']	    				    = $ArrResults[0];            $ArrData['VarId']					                = $ArrResults[0]['id'];        } else {            $ArrData['VarNew']  							    = 1;        }        $this->load->view(CNFCOMPANY.'addeditdyeintype',$ArrData);    }    public function updateDyeingInfo() {        $ArrResult                                              = array();        $VarTypeName				    						= xssclean($this->input->post('mn'));        $VarStatus												= xssclean($this->input->post('s'));        $VarId       											= xssclean($this->input->post('id'));        $VarUpdatedBy											= fnGetUserLoggedInfo();        $this->db->select('companyid');        $this->db->from(KN_USERS);        $this->db->where('id',$VarUpdatedBy);        $qry = $this->db->get();        $row = $qry->row();        if (isset($row))        {            $companyid = $row->companyid;        }        if($VarTypeName<>'') {            $ArrUpdateData                                      = array('id'=>$VarId,'dyeingname'=>$VarTypeName,                'status'=>$VarStatus,'updatedby'=>$VarUpdatedBy,'companyid'=>$companyid,'dateupdated'=>date('Y-m-d H:i:s'));            if($VarId=='' || $VarId==0) {                $ArrUpdateData['datecreated']                   = date('Y-m-d H:i:s');            }            $ArrStatus                                          = $this->mdyeintypemodel->saveDyeingTypeInfo($ArrUpdateData);            echo json_encode($ArrStatus);unset($ArrStatus);unset($ArrUpdateData);die;        } else {            $ArrResult['errcode']							    = '-1';            $ArrResult['msg']								    = 'Invalid Input!';        }        echo json_encode($ArrResult);    }    public function managedyeintype() {        $VarFrom												= xssclean($this->input->post('rfrom'));        $VarTypeName											= xssclean($this->input->post('mn'));        $VarStatus  											= xssclean($this->input->post('s'));        $sortbyClickEvent									    = xssclean($this->input->post('sortorder'));        $VarColumnId									        = xssclean($this->input->post('columnId'));        $VarAlphaFilter	   										= xssclean($this->input->post('afilter'));        if($VarFrom==1) {            $VarURLSegment										= 4;            $this->load->library('pagination');            $config['base_url']									= base_url().CNFCOMPANY.'mdyeintype/managedyeintype/';            $config['total_rows']								= $this->mdyeintypemodel->fnCountDyeingType($VarTypeName,$VarStatus,$VarAlphaFilter);//echo '<pre>'; print_r($config['total_rows']);            $config['per_page']									= $this->limit;            $config['uri_segment']								= $VarURLSegment;            $offset												= $this->uri->segment($VarURLSegment);            $this->pagination->initialize($config);            $sortby												= "d.dateupdated";            $sortorder											= "desc";            if($sortbyClickEvent <> '') {                $sortorder = $sortbyClickEvent;            }            if($VarColumnId <> '') {                $Arrcolumns = array('d.dyeingname','d.status','d.updatedby','d.dateupdated');                if(array_key_exists($VarColumnId,$Arrcolumns)) {                    $sortby = $Arrcolumns[$VarColumnId];                }            }            $ArrDyeingTypeList								= $this->mdyeintypemodel->fnListDyeingType($VarTypeName,$VarStatus,$this->limit,$offset,$sortby,$sortorder,$VarAlphaFilter)->result();//echo '<pre>'; print_r($ArrDyeingTypeList); die('');            $data['pagination']									= $this->pagination->create_linkswithajax('DyeingType');            $i=0;            $ArrFnlList										    = array();            $ArrStatus                                          = unserialize(ARRSTATUS);            foreach ($ArrDyeingTypeList as $ObjDyeing){                $ArrFnlList[$i]['id']						    = $ObjDyeing->id;                $ArrFnlList[$i]['n']						    = $ObjDyeing->dyeingname;                $ArrFnlList[$i]['ub']						    = $ObjDyeing->contactname;                $ArrFnlList[$i]['s']						    = $ArrStatus[$ObjDyeing->status];                $ArrFnlList[$i]['du']						    = date('d-m-Y H:i:s',strtotime($ObjDyeing->dateupdated));                $i=$i+1;            }            echo json_encode(array('errcode'=>1,'cn'=>$config['total_rows'],'ct'=>$i,'re'=>$ArrFnlList,'pa'=>base64_encode($data['pagination'])));            unset($ArrFnlList);            die;        } else {            $this->load->view(CNFCOMPANY.'managedyeintype');        }    }    function changemStatus() {        $VarActDeactOption										= xssclean($this->input->post('actdeactFabType'));        $VarCid 	   										    = xssclean($this->input->post('cid'));        if($VarActDeactOption <> '' && $VarCid <> '') {            $this->mdyeintypemodel->fnChangeComStat($VarCid,$VarActDeactOption);        }        echo json_encode(array('errcode'=> 1));        die;    }    function delDeyingTypeInfo() {        $VarTypeId                                            = xssclean($this->input->post('id'));        $VarUpdatedBy                                           = fnGetUserLoggedInfo();        if($VarTypeId>=1) {            $ArrResult             					            = $this->mdyeintypemodel->fnDelDeyingType($VarTypeId,$VarUpdatedBy);        } else {            $ArrResult['errcode']						        = -1;            $ArrResult['msg']							        = '';        }        echo json_encode($ArrResult);    }}